/* Work OS: dynamic boards, independent from the legacy task model. */
let wsState={workspaces:[],boards:[],fields:[],items:[]},wsId=null,boardId=null,wsMode='table',wsQuery='';
const wsTypes={text:'Texto',number:'Número',date:'Data',checkbox:'Checkbox',status:'Status'};
function node(tag,text,cls){const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n}
function wsButton(label,fn,cls='plain'){const b=node('button',label,cls);b.type='button';b.onclick=fn;return b}
async function wsLoad(){try{wsState=await api('/api/workspaces');if(!wsState.workspaces.some(w=>w.id===wsId))wsId=wsState.workspaces[0]?.id??null;wsDraw()}catch(e){$('#workspaces').replaceChildren(node('p',e.message,'notice'))}}
async function wsWrite(method,data){try{const result=await api('/api/workspaces',{method,body:JSON.stringify(data)});if(data.action==='workspace')wsId=result.id;if(data.action==='board')boardId=result.id;await wsLoad();toast('Alteração salva.');}catch(e){toast(e.message);await wsLoad()}}
function wsCreate(action,extra={}){const modal=$('#modal'),d=node('div',undefined,'dialog'),form=node('form',undefined,'form'),name=node('input');name.required=true;name.maxLength=120;name.placeholder='Nome';const names={workspace:'Novo workspace',board:'Novo quadro',field:'Novo campo',item:'Novo registro',rename:'Renomear registro'};d.append(node('h2',names[action]));form.append(name);let type;if(action==='field'){type=node('select');for(const [k,v] of Object.entries(wsTypes)){const o=node('option',v);o.value=k;type.append(o)}form.append(type)}const actions=node('div',undefined,'actions');actions.append(wsButton('Cancelar',closeModal));const save=node('button','Salvar','primary');save.type='submit';actions.append(save);form.append(actions);form.onsubmit=async e=>{e.preventDefault();save.disabled=true;await wsWrite(action==='rename'?'PATCH':'POST',{...extra,action,name:name.value,...(type?{type:type.value}:{})});closeModal()};d.append(form);modal.replaceChildren(d);modal.classList.add('open');name.focus()}
function wsDraw(){const root=$('#workspaces');if(!root)return;root.replaceChildren();const shell=node('div',undefined,'ws-shell'),side=node('aside',undefined,'ws-side'),main=node('section',undefined,'ws-main');shell.append(side,main);root.append(shell);side.append(node('h3','Ambientes'));if(current?.is_admin)side.append(wsButton('+ Workspace',()=>wsCreate('workspace')));for(const w of wsState.workspaces){side.append(wsButton(w.name,()=>{wsId=w.id;boardId=null;wsDraw()},'ws-link'+(wsId===w.id?' selected':'')))}const boards=wsState.boards.filter(b=>b.workspace_id===wsId);if(!boards.some(b=>b.id===boardId))boardId=boards[0]?.id??null;side.append(node('h3','Quadros'));if(wsId&&current?.is_admin)side.append(wsButton('+ Quadro',()=>wsCreate('board',{workspace_id:wsId})));for(const b of boards)side.append(wsButton(b.name,()=>{boardId=b.id;wsDraw()},'ws-link'+(boardId===b.id?' selected':'')));const b=boards.find(b=>b.id===boardId);if(!b){main.append(node('h2','Seu espaço de trabalho'),node('p','Crie um workspace e um quadro para começar.','sub'));return}main.append(node('h2',b.name));const tools=node('div',undefined,'work-tools');if(can('create'))tools.append(wsButton('+ Registro',()=>wsCreate('item',{board_id:b.id}),'primary'));if(current?.is_admin)tools.append(wsButton('+ Campo',()=>wsCreate('field',{board_id:b.id})));for(const [v,l] of [['table','Tabela'],['kanban','Kanban'],['summary','Resumo']])tools.append(wsButton(l,()=>{wsMode=v;wsDraw()},'tab'+(wsMode===v?' active':'')));const search=node('input');search.placeholder='Buscar registros';search.value=wsQuery;search.setAttribute('aria-label','Buscar registros');tools.append(search);main.append(tools);const results=node('div',undefined,'work-grid');main.append(results);const fields=wsState.fields.filter(f=>f.board_id===b.id),items=wsState.items.filter(i=>i.board_id===b.id);function draw(){results.replaceChildren();const filtered=items.filter(i=>i.title.toLocaleLowerCase().includes(wsQuery.toLocaleLowerCase()));const status=fields.find(f=>f.type==='status');if(wsMode==='summary'){results.append(node('h3',filtered.length+' registros'));for(const f of fields.filter(f=>f.type==='number'))results.append(node('p',f.name+': '+filtered.reduce((sum,i)=>sum+(Number(i.values?.[f.id])||0),0).toLocaleString('pt-BR')));return}if(wsMode==='kanban'){if(!status){results.append(node('p','Adicione um campo Status para usar o Kanban.'));return}const grid=node('div',undefined,'board');for(const stage of ['Sem status','A fazer','Em andamento','Concluído']){const col=node('div',undefined,'col');col.append(node('h3',stage));for(const i of filtered.filter(i=>(i.values?.[status.id]||'Sem status')===stage)){const card=node('div',undefined,'card');card.append(node('b',i.title),wsCell(i,status));col.append(card)}grid.append(col)}results.append(grid);return}const table=node('table'),head=node('tr');head.append(node('th','Registro'));for(const f of fields)head.append(node('th',f.name));head.append(node('th','Ações'));const thead=node('thead');thead.append(head);table.append(thead);const tbody=node('tbody');for(const i of filtered){const tr=node('tr');tr.append(node('td',i.title));for(const f of fields){const td=node('td');td.append(wsCell(i,f));tr.append(td)}const td=node('td');if(can('edit'))td.append(wsButton('Editar nome',()=>wsCreate('rename',{id:i.id})));if(can('delete'))td.append(wsButton('Excluir',()=>{if(confirm('Excluir este registro?'))wsWrite('DELETE',{action:'item',id:i.id})}));tr.append(td);tbody.append(tr)}table.append(tbody);results.append(table);if(!filtered.length)results.append(node('p','Nenhum registro.','empty'))}search.oninput=()=>{wsQuery=search.value;draw()};draw()}
function wsCell(item,field){let v=item.values?.[field.id]??null,input;if(field.type==='status'){input=node('select');for(const st of ['','A fazer','Em andamento','Concluído']){const o=node('option',st||'Sem status');o.value=st;input.append(o)}input.value=v??''}else{input=node('input');input.type=field.type==='text'?'text':field.type;input.setAttribute('aria-label',field.name);if(field.type==='checkbox')input.checked=Boolean(v);else input.value=v??'';if(field.type==='number')input.step='any';if(field.type==='text')input.maxLength=2000}input.disabled=!can('edit');input.onchange=()=>{const value=field.type==='checkbox'?input.checked:input.value===''?null:field.type==='number'?Number(input.value):input.value;input.disabled=true;wsWrite('PATCH',{action:'value',id:item.id,field_id:field.id,value})};return input}
